(()=>{'use strict';const $=id=>document.getElementById(id),main=$('main'),view=document.body.dataset.view,usd=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const seed={customers:[{id:1,name:'Jamie Parker',address:'742 Oak Ridge Dr',price:100,crew:'North',status:'Completed',x:1,y:4},{id:2,name:'Taylor Reed',address:'1189 Maple Ave',price:110,crew:'North',status:'In progress',x:2,y:2},{id:3,name:'Alex Morgan',address:'203 Wilder Ct',price:95,crew:'North',status:'Pending',x:4,y:1},{id:4,name:'Sam Brooks',address:'56 Pine Hollow',price:105,crew:'North',status:'Pending',x:6,y:3},{id:5,name:'Casey Rivera',address:'901 Cedar Ln',price:120,crew:'North',status:'Pending',x:7,y:4},{id:6,name:'Jordan Ellis',address:'104 Oak Drive',price:110,crew:'South',status:'Pending',x:2,y:5},{id:7,name:'Drew Collins',address:'412 Maple Ave',price:100,crew:'South',status:'Pending',x:5,y:5},{id:8,name:'Robin Lane',address:'82 Palm Way',price:100,crew:'South',status:'Completed',x:7,y:2}],invoices:[{id:1001,customer:1,amount:50,status:'Paid'},{id:1002,customer:2,amount:55,status:'Paid'},{id:1003,customer:3,amount:47.5,status:'Processing'},{id:1004,customer:4,amount:52.5,status:'Failed'}],agents:{customer:true,routing:true,company:false,min:45,max:85,radius:1.5,margin:30},logs:['Sample: two nearby inquiries could fit Tuesday’s North route.','Sample: review access instructions before issuing an estimate.']};seed.demoDate='2026-10-06';seed.previousRevenue=7500;seed.previousCustomers=39;seed.settings={company:'Greenline Lawn Care',owner:'Jamie Davis',start:'08:00',end:'17:00',photoRequired:true};seed.history=[{month:'2026-07',revenue:6800,costs:5300,retention:91},{month:'2026-08',revenue:7500,costs:5700,retention:93},{month:'2026-09',revenue:8400,costs:6200,retention:95}];seed.customers.forEach((c,i)=>{c.price=200;if(c.id===2)c.status='Completed';c.jobDate=seed.demoDate;c.scheduledTime=['09:14','08:46','09:45','10:20','11:15','11:50','13:00','13:40'][i];c.proof=c.status==='Completed';c.notes='Keep gate closed after service. Review yard access before starting.'});const streets=['Oak Ridge Dr','Maple Ave','Palm Way','Cedar Ln','Pine Hollow','Wilder Ct'];for(let i=8;i<42;i++){seed.customers.push({id:i+1,name:'Sample Customer '+(i+1),address:(140+i*11)+' '+streets[i%6],price:200,crew:i%2?'South':'North',status:i<19?'Completed':i==19?'In progress':'Pending',jobDate:i<22?seed.demoDate:'2026-10-'+String(7+Math.floor((i-22)/7)).padStart(2,'0'),scheduledTime:String(8+Math.floor((i%10)/2)).padStart(2,'0')+':'+(i%2?'30':'00'),proof:i<19,notes:'Sample access instructions. Confirm details before service.',x:1+i%7,y:1+i%5})}seed.logs=['Sample: North crew completed 742 Oak Ridge Dr. Completion photo recorded.','Sample: South crew completed 82 Palm Way.','Sample: 203 Wilder Ct is next on North crew’s route.','Sample: Thursday’s route has room for a nearby customer.'];seed.valueAssumptions={low:2,high:3,goal:100000};let state;try{state=JSON.parse(localStorage.getItem('mm-office-demo-v2'))}catch{}if(!state?.customers||!state?.invoices)state=structuredClone(seed);state.valueAssumptions=state.valueAssumptions||{low:2,high:3,goal:100000};let crew='North',search='',selectedDate=new URLSearchParams(location.search).get('day')||state.demoDate,mapZoom=1,showAllMap=false;const isoDate=d=>/^\d{4}-\d{2}-\d{2}$/.test(d);if(!isoDate(selectedDate))selectedDate=state.demoDate;const scheduled=()=>state.customers.filter(c=>c.jobDate===selectedDate);const dateLabel=()=>new Date(selectedDate+'T12:00:00').toLocaleDateString('en-US',{weekday:'short',month:'short',day:'numeric'});function save(){try{localStorage.setItem('mm-office-demo-v2',JSON.stringify(state))}catch{toast('Browser storage unavailable. Changes last until this page closes.')}}let timer;function toast(t){$('toast').textContent=t;$('toast').classList.add('visible');clearTimeout(timer);timer=setTimeout(()=>$('toast').classList.remove('visible'),4500)}function badge(s){return `<span class="status ${s.toLowerCase().replace('in progress','progress')}">${esc(s)}</span>`}function metric(icon,label,value,note,extra=''){return `<article class="card metric"><span class="metric-icon" aria-hidden="true">${icon}</span><div><span class="label">${label}</span><strong>${value}</strong><small>${note}</small>${extra}</div></article>`}function customer(id){return state.customers.find(c=>c.id===Number(id))}function route(){return scheduled().filter(c=>c.crew===crew)}function coords(c){return [45+c.x*68,32+c.y*43]}function map(list){const lines=list.map(c=>coords(c).join(',')).join(' ');return `<div class="map-frame"><svg class="map" viewBox="${300-300/mapZoom} ${150-150/mapZoom} ${600/mapZoom} ${300/mapZoom}" role="img" aria-label="Schematic sample route with ${list.length} stops"><rect width="600" height="300" fill="#edf3e9"/><image href="neighborhood-map.jpg" x="0" y="0" width="600" height="300" preserveAspectRatio="xMidYMid slice"/><polyline points="${lines}" stroke="#507b5f" stroke-width="9" fill="none" stroke-linejoin="round"/><polyline points="${lines}" stroke="#c2f600" stroke-width="4" fill="none" stroke-linejoin="round"/>${list.map((c,i)=>{const[x,y]=coords(c);return `<g><circle cx="${x}" cy="${y}" r="17" fill="${c.status==='Completed'?'#178744':c.status==='In progress'?'#e5aa27':'#06271d'}" stroke="white" stroke-width="3"/><text x="${x}" y="${y+5}" text-anchor="middle" fill="white">${i+1}</text><title>${esc(c.address)} · ${esc(c.status)}</title></g>`}).join('')}</svg><div class="map-controls"><button data-map="in" aria-label="Zoom map in">+</button><button data-map="out" aria-label="Zoom map out">−</button><button data-map="reset" aria-label="Reset map view">⌖</button></div></div><div class="map-legend"><span><i class="pending"></i>Planned stop</span><span><i class="done"></i>Completed</span><span><i class="working"></i>In progress</span><span>North crew</span><span>South crew</span></div><p class="map-note">Illustrative sample map · Live geography and truck GPS not connected</p>`}function activities(all=false){const records=scheduled().filter(c=>c.status!=='Pending');return `<ul class="activity">${records.slice(0,all?100:4).map(c=>`<li><span class="status-icon">${c.status==='Completed'?'✓':'◷'}</span><time>${esc(c.scheduledTime||'09:00')}</time><div><button class="activity-link" data-customer="${c.id}">${esc(c.status==='Completed'?'Job completed':'Crew on site')}</button><small>${esc(c.address)}</small></div>${c.proof?'<img class="proof-thumb" src="sample-yard.jpg" alt="Illustrative sample property image">':''}</li>`).join('')}<li><span class="status-icon">⌁</span><time>08:20</time><div><b>North crew en route</b><small>Next stop: 203 Wilder Ct</small></div></li><li><span class="status-icon">◉</span><time>07:30</time><div><b>Day started</b><small>Sample crew check-in</small></div></li></ul>`}function valueScenario(){const h=state.history?.at(-1),previous=state.history?.at(-2),a=state.valueAssumptions,annual=h?(h.revenue-h.costs)*12:0,mid=(a.low+a.high)/2;return{eligible:annual>0,month:h?.month,annual,low:annual*a.low,high:annual*a.high,mid:annual*mid,change:previous?annual*mid-(previous.revenue-previous.costs)*12*mid:null,goal:a.goal,percent:Math.min(100,Math.max(0,annual*mid/a.goal*100))}}function shortValue(n){return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',notation:'compact',maximumFractionDigits:1}).format(n).replace('K','k')}function updateValueBadge(){const v=valueScenario(),box=$('sidebar-business-value');if(!box)return;box.innerHTML=`<div class="sidebar-value-label">Your business value</div><div class="sidebar-value-number">${v.eligible?shortValue(v.mid):'Not estimated'}</div><div class="sidebar-value-meta">Illustrative sample${v.eligible&&v.change!==null?' · '+(v.change>=0?'+':'−')+shortValue(Math.abs(v.change)):''}</div><div class="sidebar-milestone"><div><span>Next milestone</span><strong>${shortValue(v.goal)}</strong></div><div class="sidebar-milestone-track"><progress value="${v.percent}" max="100" aria-label="Sample business value milestone progress"></progress><b>${Math.round(v.percent)}%</b></div></div><a class="sidebar-grow" href="growth.html">Grow this value</a><div class="sidebar-value-links"><a href="valuation.html">View history</a><button data-value-assumptions aria-label="View business value assumptions and set milestone">ⓘ</button></div>`}function valueIndicator(){const v=valueScenario();return `<section class="value-today" aria-labelledby="business-value-heading"><div class="value-main"><div class="value-kicker"><span>BUILD AN ASSET. NOT JUST A SCHEDULE.</span><b>ILLUSTRATIVE SAMPLE</b></div><h2 id="business-value-heading">Your business value today is</h2><p class="value-amount">${v.eligible?usd(v.mid):'Not estimated yet'}</p><p class="value-range">${v.eligible?'Sample scenario range: '+usd(v.low)+' – '+usd(v.high):'Add a month with positive recorded surplus to explore this scenario.'}</p>${v.eligible&&v.change!==null?`<span class="value-change ${v.change>=0?'up':'down'}">${v.change>=0?'↑':'↓'} ${usd(Math.abs(v.change))} ${v.change>=0?'higher':'lower'} than the previous sample month</span>`:''}<p class="value-basis">${v.eligible?'Annualized surplus from '+esc(v.month)+' × your assumed multiple.':''} An illustrative scenario, not a market appraisal or lender-approved value.</p></div><div class="value-next"><p class="eyebrow">YOUR NEXT MILESTONE</p><strong>${usd(v.goal)}</strong><div class="milestone-progress"><progress max="100" value="${v.percent}" aria-label="Progress toward sample business value milestone"></progress><span>${Math.round(v.percent)}%</span></div><p>${v.eligible?(v.mid>=v.goal?'Your sample scenario reaches this milestone. Set your next goal.':usd(v.goal-v.mid)+' to your sample goal. Explore what better earnings could change.'):'Start with documented earnings, then plan your next stage.'}</p><a href="growth.html" class="button primary">Grow this value</a><button class="value-assumptions" data-value-assumptions>View assumptions & set milestone</button></div></section>`}function bindValue(){document.querySelectorAll('[data-value-assumptions]').forEach(b=>b.onclick=()=>{const v=valueScenario(),a=state.valueAssumptions;showDialog(`<p class="eyebrow">ILLUSTRATIVE VALUE SCENARIO</p><h2>See what’s behind the number</h2><p>${v.eligible?usd(v.annual)+' annualized operating surplus from the latest sample month.':'No positive recorded operating surplus is available.'}</p><p class="help">The demonstration assumes a 2–3× multiple by default. This range is not validated against lawn-care business sales. Surplus is before omitted costs, taxes and owner compensation. Debt, equipment and transferability are not modeled.</p><form id="value-assumptions-form" class="dialog-form"><div class="detail-list"><label>Low assumed multiple<input id="value-low" type="number" min="0.1" max="10" step="0.1" value="${a.low}" required></label><label>High assumed multiple<input id="value-high" type="number" min="0.1" max="10" step="0.1" value="${a.high}" required></label></div><label>My next milestone ($)<input id="value-goal" type="number" min="1" max="10000000" value="${a.goal}" required></label><button class="button primary">Update sample scenario</button><p class="help">A real valuation needs verified earnings, assets, liabilities and comparable sales.</p><p id="value-error" role="status" class="error"></p></form>`,()=>{$('value-assumptions-form').onsubmit=e=>{e.preventDefault();const low=+$('value-low').value,high=+$('value-high').value,goal=+$('value-goal').value;if(!Number.isFinite(low)||!Number.isFinite(high)||!Number.isFinite(goal)||low<.1||high<low||high>10||goal<1||goal>10000000){$('value-error').textContent='Set a positive milestone and a high multiple at least as large as the low multiple.';return}state.valueAssumptions={low,high,goal};save();$('detail').close();render();toast('Sample value assumptions and milestone updated.')}})})}function overview(){const mrr=state.customers.reduce((a,c)=>a+c.price,0),done=scheduled().filter(c=>c.status==='Completed').length,total=scheduled().length,pct=total?Math.round(done/total*100):0,revChange=Math.round((mrr/state.previousRevenue-1)*100),customerChange=Math.round((state.customers.length/state.previousCustomers-1)*100);updateValueBadge();const v=valueScenario();$('page-title').innerHTML='Your Business '+(v.eligible?'<span class="heading-value">(valued '+shortValue(v.mid)+')</span>':'')+', at a glance.';main.innerHTML=`<div class="metrics">${metric('▥','Recurring revenue',usd(mrr),`<span class="green">↑ ${revChange}%</span> vs last sample month`,'<span class="spark-bars" aria-label="Illustrative revenue trend"><i></i><i></i><i></i><i></i><i></i></span>')}${metric('◉','Active customers',state.customers.length,`<span class="green">↑ ${customerChange}%</span> vs last sample month`,'<span class="spark-bars" aria-label="Illustrative customer trend"><i></i><i></i><i></i><i></i><i></i></span>')}${metric('✓',"Today’s jobs",done+' / '+total,'Sample day · '+dateLabel(),`<div class="progress-row"><progress value="${done}" max="${total||1}" aria-label="Completed jobs"></progress><span>${pct}% complete</span></div>`)}</div><div class="columns"><section class="card route-panel"><div class="section-head"><h2>Today’s route</h2><div class="route-tools"><label class="sr-only" for="dash-crew">Select crew</label><select id="dash-crew"><option value="North" ${crew==='North'?'selected':''}>North crew</option><option value="South" ${crew==='South'?'selected':''}>South crew</option></select><button class="icon-button" id="previous-day" aria-label="Previous sample day">‹</button><button class="button" id="select-day">${dateLabel()}</button><button class="icon-button" id="expand-map" aria-label="Expand route map">⛶</button></div></div>${map(route())}</section><section class="card"><div class="section-head"><h2>Today’s operations</h2><a class="button compact" href="activity.html?day=${selectedDate}">View all</a></div>${activities()}</section></div><div class="bottom-grid"><section class="card"><div class="section-head"><h2>Weekly revenue</h2><label class="sr-only" for="revenue-period">Revenue period</label><select id="revenue-period"><option value="current">This sample week</option><option value="previous">Previous sample week</option></select></div><div id="weekly-chart"></div></section><section class="card"><div class="section-head"><h2>Next jobs</h2><a class="button compact" href="routes.html?day=${selectedDate}">View route</a></div><ul class="jobs">${route().filter(c=>c.status==='Pending').slice(0,3).map((c,i)=>`<li><span class="number">${i+1}</span><div><button class="activity-link" data-customer="${c.id}">${esc(c.address)}</button><small>Lawn care · 30 min</small></div><time class="job-time">${esc(c.scheduledTime||'10:00')}</time></li>`).join('')||'<li>No pending jobs for this crew on this sample day.</li>'}</ul></section><section class="card value-card"><h2>What grows your business value?</h2><ul class="value-drivers"><li><b>Recurring revenue</b><span>${usd(mrr)} / month in sample contracts</span></li><li><b>Customer retention</b><span>${state.history.at(-1)?.retention||0}% in the latest sample month</span></li><li><b>Documented earnings</b><span>Track costs and owner involvement</span></li></ul><a href="valuation.html" class="button dark">Review my value history</a></section></div>`;$('dash-crew').onchange=e=>{crew=e.target.value;overview()};$('previous-day').onclick=()=>{const d=new Date(selectedDate+'T12:00:00');d.setDate(d.getDate()-1);selectedDate=d.toISOString().slice(0,10);overview()};$('select-day').onclick=datePicker;$('expand-map').onclick=()=>{showDialog('<h2>'+esc(crew)+' crew route</h2>'+map(route()));$('detail').classList.add('map-dialog');bindMap()};$('revenue-period').onchange=weeklyChart;weeklyChart();bindMap();bindCustomers();bindValue()}function weeklyChart(){const prev=$('revenue-period').value==='previous',values=prev?[350,650,450,750,700,500,200]:[450,800,600,1100,950,700,250],max=1200;$('weekly-chart').innerHTML=`<div class="revenue-chart"><div class="axis"><span>$1.2k</span><span>$800</span><span>$400</span><span>$0</span></div><div class="chart">${values.map((v,i)=>`<div><i style="height:${v/max*100}%" title="${['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'][i]}: ${usd(v)}"></i><span>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</span></div>`).join('')}</div></div><p class="chart-label">${usd(values.reduce((a,b)=>a+b,0))} collected · Sample weekly figures</p>`}function datePicker(){showDialog(`<h2>Choose a sample service day</h2><form id="date-form" class="dialog-form"><label>Day<input id="day-input" type="date" value="${selectedDate}" required></label><button class="button primary">Show this day</button><button type="button" class="button" id="restore-day">Back to sample Tuesday</button></form>`,()=>{$('date-form').onsubmit=e=>{e.preventDefault();selectedDate=$('day-input').value;$('detail').close();render()};$('restore-day').onclick=()=>{selectedDate=state.demoDate;$('detail').close();render()}})}function bindMap(){document.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{mapZoom=b.dataset.map==='reset'?1:Math.max(1,Math.min(2.5,mapZoom+(b.dataset.map==='in'?.25:-.25)));document.querySelectorAll('.map').forEach(m=>m.setAttribute('viewBox',`${300-300/mapZoom} ${150-150/mapZoom} ${600/mapZoom} ${300/mapZoom}`))})}function bindCustomers(){document.querySelectorAll('[data-customer]').forEach(b=>b.onclick=()=>customerDetail(Number(b.dataset.customer)))}function customerDetail(id){const c=customer(id);if(!c)return;showDialog(`<p class="eyebrow">SAMPLE CUSTOMER & JOB</p><h2>${esc(c.name)}</h2><p>${esc(c.address)}</p><dl class="detail-list"><div><dt>Recurring / month</dt><dd>${usd(c.price)}</dd></div><div><dt>Crew</dt><dd>${esc(c.crew)}</dd></div><div><dt>Job status</dt><dd>${esc(c.status)}</dd></div><div><dt>Next sample visit</dt><dd>${esc(c.jobDate||state.demoDate)}</dd></div></dl><h3 style="margin-top:22px">Access notes</h3><p>${esc(c.notes||'No sample access instructions recorded.')}</p><h3>Completion proof</h3><p>${c.proof?'Illustrative sample completion photo recorded.':'No completion photo in this sample record.'}</p>${c.proof?'<img class="sample-proof" src="sample-yard.jpg" alt="Illustrative lawn completion photo"><p class="help">Illustrative image, not a photo from this property.</p>':''}<a class="button primary" href="routes.html?day=${esc(c.jobDate||state.demoDate)}">Open scheduled route</a>`)}function routes(){const list=route(),done=list.filter(c=>c.status==='Completed').length;main.innerHTML=`<div class="toolbar"><label>Crew<select id="crew-select"><option ${crew==='North'?'selected':''}>North</option><option ${crew==='South'?'selected':''}>South</option></select></label><button class="button primary" id="optimize">Optimize sample route</button><button class="button" id="route-day">${dateLabel()}</button></div><div class="route-layout"><section class="card"><h2>${crew} crew</h2><div class="route-summary"><div><strong>${list.length}</strong>stops</div><div><strong>${done}</strong>complete</div><div><strong>${list.length*30}</strong>service min</div></div>${list.map((c,i)=>`<article class="route-stop"><span class="number">${i+1}</span><div><b>${esc(c.address)}</b><p>${esc(c.name)} · Gate details in customer record</p>${badge(c.status)}<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap"><button class="button" data-complete="${c.id}" ${c.status==='Completed'?'disabled':''}>Mark complete</button><select data-assign="${c.id}" aria-label="Assign ${esc(c.address)} to crew"><option ${c.crew==='North'?'selected':''}>North</option><option ${c.crew==='South'?'selected':''}>South</option></select></div></div></article>`).join('')||'<p class="empty">No sample stops assigned.</p>'}</section><section class="card route-map"><div class="section-head"><h2>Route sequence</h2><span class="status">Sample map</span></div>${map(list)}<h3 style="margin-top:24px">Routing activity</h3><p class="muted">${esc(state.logs[0])}</p></section></div>`;$('route-day').onclick=datePicker;bindMap();$('crew-select').onchange=e=>{crew=e.target.value;routes()};$('optimize').onclick=optimize;main.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>complete(Number(b.dataset.complete)));main.querySelectorAll('[data-assign]').forEach(s=>s.onchange=()=>{customer(s.dataset.assign).crew=s.value;save();routes();toast('Sample stop moved. No crew notification sent.')})}function complete(id){const c=customer(id);if(!c)throw Error('Unknown sample customer');c.status='Completed';c.proof=true;state.logs.unshift('Sample job completed at '+c.address);save();render();toast('Sample job completed. No invoice or customer message sent.');return{customerId:id,status:c.status}}function optimize(){let remaining=route().filter(c=>c.status!=='Completed'),ordered=route().filter(c=>c.status==='Completed'),last=ordered.at(-1)||{x:0,y:0};while(remaining.length){remaining.sort((a,b)=>Math.hypot(a.x-last.x,a.y-last.y)-Math.hypot(b.x-last.x,b.y-last.y));last=remaining.shift();ordered.push(last)}let others=state.customers.filter(c=>c.crew!==crew||c.jobDate!==selectedDate);state.customers=[...others,...ordered];state.logs.unshift('Sample '+crew+' route sequenced by proximity. Live drive times and weather are not connected.');save();routes();toast('Sample route reordered by proximity. No dispatch sent.')}function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td data-label="${headers[i]}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}function customers(){const list=state.customers.filter(c=>(c.name+' '+c.address).toLowerCase().includes(search.toLowerCase()));main.innerHTML=`<div class="toolbar"><label>Search<input id="search" type="search" placeholder="Name or yard address" value="${esc(search)}"></label><button class="button primary" id="add-customer">Add sample customer</button></div><section class="card"><div class="section-head"><h2>Your customer book</h2><span class="status">${list.length} sample accounts</span></div>${table(['Customer','Property','Recurring / month','Crew','Details'],list.map(c=>[esc(c.name),esc(c.address),usd(c.price),esc(c.crew),`<button class="table-btn" data-detail="${c.id}">View customer</button>`]))}${list.length?'':'<p class="empty">No matching sample customers.</p>'}</section>`;$('search').oninput=e=>{search=e.target.value;const pos=e.target.selectionStart;customers();$('search').focus();$('search').setSelectionRange(pos,pos)};$('add-customer').onclick=()=>showDialog(`<h2>Add sample customer</h2><p class="help">Use fictional information. This record stays in this browser.</p><form id="customer-form" class="dialog-form"><label>Name<input name="name" maxlength="80" required></label><label>Address<input name="address" maxlength="150" required></label><label>Monthly recurring price ($)<input name="price" type="number" min="1" max="10000" value="100" required></label><button class="button primary">Add sample customer</button></form>`,()=>{$('customer-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);state.customers.push({id:Date.now(),name:f.get('name').trim(),address:f.get('address').trim(),price:Number(f.get('price')),crew:'North',status:'Pending',jobDate:state.demoDate,scheduledTime:'14:00',x:3,y:3});save();$('detail').close();customers();toast('Sample customer added in this browser.')}});main.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>{const c=customer(b.dataset.detail);showDialog(`<p class="eyebrow">SAMPLE CUSTOMER</p><h2>${esc(c.name)}</h2><p>${esc(c.address)}</p><dl class="detail-list"><div><dt>Recurring / month</dt><dd>${usd(c.price)}</dd></div><div><dt>Crew</dt><dd>${esc(c.crew)}</dd></div><div><dt>Today</dt><dd>${esc(c.status)}</dd></div><div><dt>Service cadence</dt><dd>2 visits / month</dd></div></dl><p class="help">Gate codes, agreements and contact information will belong in a connected customer record.</p>`)})}function financials(){const paid=state.invoices.filter(i=>i.status==='Paid').reduce((a,i)=>a+i.amount,0),pending=state.invoices.filter(i=>i.status!=='Paid').reduce((a,i)=>a+i.amount,0);main.innerHTML=`<div class="metrics">${metric('▥','Collected gross',usd(paid),'Sample paid invoices')}${metric('◷','Awaiting collection',usd(pending),'Processing and failed sample invoices')}${metric('✓','Net payout','Not connected','Payment provider setup required')}</div><section class="card"><div class="section-head"><h2>Transactions</h2><span class="status">Sample invoices</span></div>${table(['Customer','Property','Amount','Status','Action'],state.invoices.map(i=>[esc(customer(i.customer).name),esc(customer(i.customer).address),usd(i.amount),badge(i.status),i.status==='Failed'?`<button class="table-btn" data-retry="${i.id}">Preview recovery</button>`:'—']))}<p class="help">No real payment details are stored here. The proposed 1.5% platform fee is separate from processing fees. Live payouts depend on payment-provider enrollment.</p></section>`;main.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>showDialog(`<h2>Payment recovery preview</h2><p>Hi ${esc(customer(state.invoices.find(i=>i.id===Number(b.dataset.retry)).customer).name)}, your lawn service payment needs an updated payment method. Please visit your secure customer portal.</p><p class="help">Draft preview only. No SMS, email, or card retry will be sent.</p><button class="button primary" id="review-draft">Mark sample draft reviewed</button>`,()=>{$('review-draft').onclick=()=>{$('detail').close();toast('Sample recovery draft reviewed. Nothing was sent.')}}))}function agents(){const a=state.agents;main.innerHTML=`<div class="agent-grid"><section class="card"><span class="agent-top">✧</span><h2>Customer agent</h2><p class="muted">Review quote rules before automating new inquiries.</p><label class="switch"><input id="agent-customer" type="checkbox" ${a.customer?'checked':''}>Enable in sample workspace</label><label>Minimum per visit ($)<input id="agent-min" type="number" min="1" max="1000" value="${a.min}"></label><label>Maximum per visit ($)<input id="agent-max" type="number" min="1" max="1000" value="${a.max}"></label><p class="help">Instant Quotes is a separate proposed add-on. Property conditions need confirmation.</p></section><section class="card"><span class="agent-top">⌁</span><h2>Routing agent</h2><p class="muted">Keep nearby work together, with owner review.</p><label class="switch"><input id="agent-routing" type="checkbox" ${a.routing?'checked':''}>Enable in sample workspace</label><label>Neighborhood radius (miles)<input id="agent-radius" type="number" min="0.1" max="20" step="0.1" value="${a.radius}"></label><p class="help">Sample proximity settings. Live weather, road travel and crew GPS require integrations.</p></section><section class="card"><span class="agent-top">▥</span><h2>Company agent</h2><p class="muted">Review retention, pricing and operating margins.</p><label class="switch"><input id="agent-company" type="checkbox" ${a.company?'checked':''}>Enable in sample workspace</label><label>Operating margin threshold (%)<input id="agent-margin" type="number" min="0" max="100" value="${a.margin}"></label><p class="help">This is the operator’s margin threshold, separate from Mow Matter’s software margin target.</p></section></div><div class="toolbar" style="margin-top:20px"><button class="button primary" id="save-agents">Save sample settings</button></div><section class="card feed"><h2>Agent activity</h2><ul>${state.logs.slice(0,6).map(l=>`<li>${esc(l)}</li>`).join('')}</ul><p class="help">Activity records and illustrative recommendations, rather than private model reasoning.</p></section>`;$('save-agents').onclick=()=>{const min=+$('agent-min').value,max=+$('agent-max').value,radius=+$('agent-radius').value,margin=+$('agent-margin').value;if(min<1||max<min||max>1000||radius<.1||radius>20||margin<0||margin>100){toast('Review quote bounds, radius and margin before saving.');return}state.agents={customer:$('agent-customer').checked,routing:$('agent-routing').checked,company:$('agent-company').checked,min,max,radius,margin};save();toast('Sample settings saved in this browser. No AI service is active.')}}function growth(){main.innerHTML=`<div class="sim-grid"><section class="card controls"><h2>Plan your next stage</h2><label>New recurring customers<output id="g-new-out"></output><input id="g-new" type="range" min="0" max="100" value="12"></label><label>Price increase per visit<output id="g-price-out"></output><input id="g-price" type="range" min="0" max="25" value="5"></label><label>Crews<output id="g-crews-out"></output><input id="g-crews" type="range" min="1" max="5" value="1"></label><label>Less travel time<output id="g-travel-out"></output><input id="g-travel" type="range" min="0" max="60" value="25"></label><p class="help">Assumptions: 2 visits/month, 30 service minutes/visit, 15 baseline travel minutes, 160 hours/crew and 10 admin hours/month.</p></section><section class="card"><p class="eyebrow">MONTHLY RECURRING REVENUE</p><h2 style="margin-top:10px">Today and your next chapter</h2><div class="projection"><div><strong id="base-value"></strong><i class="baseline" id="base-bar"></i><small>Current sample book</small></div><div><strong id="future-value"></strong><i id="future-bar"></i><small>Your scenario</small></div></div><div class="forecast-row"><div><strong id="g-increase"></strong><span>Potential monthly revenue change</span></div><div><strong id="g-capacity"></strong><span>Customer capacity</span></div><div><strong id="g-hours"></strong><span>Travel hours saved / month</span></div></div><p id="g-warning" class="help"></p><p class="help">Scenario planning only. Revenue is not profit, and real growth depends on demand, costs and available crew hours.</p></section></div>`;main.querySelectorAll('input').forEach(i=>i.oninput=forecast);forecast()}function forecast(){const count=state.customers.length,base=state.customers.reduce((a,c)=>a+c.price,0),added=+$('g-new').value,inc=+$('g-price').value,crews=+$('g-crews').value,travel=+$('g-travel').value/100,future=(count+added)*(base/count+2*inc),capacity=Math.floor((160*crews-10)*60/(30+15*(1-travel))/2);$('g-new-out').textContent=added;$('g-price-out').textContent=usd(inc);$('g-crews-out').textContent=crews;$('g-travel-out').textContent=Math.round(travel*100)+'%';$('base-value').textContent=usd(base);$('future-value').textContent=usd(future);$('base-bar').style.height=base/future*150+'px';$('future-bar').style.height='150px';$('g-increase').textContent=usd(future-base);$('g-capacity').textContent=capacity;$('g-hours').textContent=(count*2*15/60*travel).toFixed(1);$('g-warning').textContent=count+added>capacity?'Scenario exceeds crew capacity by '+(count+added-capacity)+' customers.':(capacity-count-added)+' customer slots remain under these assumptions.'}function showDialog(html,after){$('detail').classList.remove('map-dialog');$('dialog-content').innerHTML=html;$('detail').showModal();after?.()}function activity(){main.innerHTML=`<section class="card"><div class="section-head"><h2>All operations · ${dateLabel()}</h2><button id="activity-day" class="button">Choose day</button></div>${activities(true)}<h2 style="margin-top:25px">Routing and agent updates</h2><ul class="activity">${state.logs.slice(0,15).map(l=>`<li>${esc(l)}</li>`).join('')}</ul></section>`;$('activity-day').onclick=datePicker;bindCustomers()}function valuation(){updateValueBadge();const last=state.history.at(-1);main.innerHTML=`${valueIndicator()}<div class="metrics">${metric('▥','Recorded monthly revenue',usd(last.revenue),'Latest sample month · '+esc(last.month))}${metric('◉','Operating surplus',usd(last.revenue-last.costs),'Before tax, omitted costs and owner compensation')}${metric('✓','Customer retention',last.retention+'%','Sample monthly retention assumption')}</div><section class="card"><div class="section-head"><h2>Build your business value history</h2><button id="add-history" class="button primary">Add sample month</button></div><p class="muted">A buyer or lender needs more than a customer count. Keep a history of collected revenue, costs, retention, signed agreements and owner involvement.</p>${table(['Month','Collected revenue','Operating costs','Surplus','Retention'],state.history.map(h=>[esc(h.month),usd(h.revenue),usd(h.costs),usd(h.revenue-h.costs),h.retention+'%']))}<p class="help">These are fictional financial records. A market valuation and any loan decision require verified records and independent review.</p></section><div class="columns" style="margin-top:22px"><section class="card"><h2>Financial connection</h2><span class="status">Not connected</span><p style="margin-top:15px">Bank and payment-provider data are not connected to this sample workspace.</p><a href="settings.html" class="button">Review connections</a></section><section class="card"><h2>Your transferable business</h2><ul><li>Recurring customer agreements</li><li>Documented retention and collections</li><li>Routes and crew procedures</li><li>Verified operating expenses</li></ul><a href="growth.html" class="button dark">Model your next stage</a></section></div>`;bindValue();$('add-history').onclick=()=>showDialog(`<h2>Add sample monthly record</h2><form id="history-form" class="dialog-form"><label>Month<input name="month" type="month" required></label><label>Collected revenue ($)<input name="revenue" type="number" min="0" max="10000000" required></label><label>Operating costs ($)<input name="costs" type="number" min="0" max="10000000" required></label><label>Retention (%)<input name="retention" type="number" min="0" max="100" required></label><button class="button primary">Save sample month</button></form>`,()=>{$('history-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),month=f.get('month');const h={month,revenue:Number(f.get('revenue')),costs:Number(f.get('costs')),retention:Number(f.get('retention'))};state.history=state.history.filter(x=>x.month!==month);state.history.push(h);state.history.sort((a,b)=>a.month.localeCompare(b.month));save();$('detail').close();valuation();toast('Sample monthly record saved in this browser.')}})}function settings(){const a=state.settings;main.innerHTML=`<div class="columns"><section class="card"><h2>Business & crew preferences</h2><form id="settings-form" class="dialog-form"><label>Sample business name<input id="business-name" maxlength="100" value="${esc(a.company)}" required></label><label>Owner display name<input id="owner-name" maxlength="80" value="${esc(a.owner)}" required></label><div class="detail-list"><label>Workday starts<input id="work-start" type="time" value="${a.start}" required></label><label>Workday ends<input id="work-end" type="time" value="${a.end}" required></label></div><label class="switch"><input id="photo-required" type="checkbox" ${a.photoRequired?'checked':''}>Require completion photos (sample preference)</label><button class="button primary">Save sample preferences</button></form></section><section class="card"><h2>Connections</h2><ul class="activity">${['Customer database','Crew app & live GPS','Payment processing','Instant Quotes add-on','AI agents & credit balance','RealEstateAPI property & parcel data','Google Maps display, geocoding & routes'].map(x=>`<li><div><b>${x}</b><small>Not connected · Sample workspace</small></div></li>`).join('')}</ul><p class="help">These connections need account enrollment and operational integration before live use.</p></section></div><section class="card"><h2>Sample workspace data</h2><p>Preferences and sample edits stay on this browser. They are not synced across devices.</p><button id="settings-reset" class="button">Reset sample workspace</button></section>`;$('settings-form').onsubmit=e=>{e.preventDefault();if($('work-start').value>=$('work-end').value){toast('Workday end must follow start.');return}state.settings={company:$('business-name').value.trim(),owner:$('owner-name').value.trim(),start:$('work-start').value,end:$('work-end').value,photoRequired:$('photo-required').checked};save();toast('Sample preferences saved.');updateProfile()};$('settings-reset').onclick=()=>$('reset').click()}function help(){const faqs=[['Where are my changes saved?','Only in this browser’s sample workspace. Clearing browser storage removes them.'],['Does completing a job charge a customer?','No. Sample job completion updates the dashboard without charging, dispatching or sending messages.'],['How does route optimization work?','The sample uses nearby map positions to reorder stops. Road routing, traffic and weather are not connected.'],['Can I get a business valuation here?','The history view documents fictional revenue and costs. A real market valuation requires verified records and independent review.'],['What happens when I change AI settings?','Sample preferences are saved locally. They do not activate live agents, use credits or purchase an add-on.'],['Is office.mowmatter.com connected?','The hostname has been registered for this Office app. DNS verification remains pending until the Cloudflare records are added.']];main.innerHTML=`<section class="card"><h2>Help with your workspace</h2><p class="muted">Explore the sample, then review which live connections your business will need.</p>${faqs.map(([q,a])=>`<details class="faq"><summary>${q}</summary><p>${a}</p></details>`).join('')}<a class="button primary" href="settings.html" style="margin-top:22px">Review setup & connections</a></section>`}function updateProfile(){const name=state.settings?.owner||'Jamie Davis';$('profile').textContent=name.split(' ').filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase()}function globalSearch(){const q=$('global-search').value.trim().toLowerCase(),box=$('search-results');if(!q){box.hidden=true;return}const found=state.customers.filter(c=>(c.name+' '+c.address).toLowerCase().includes(q)).slice(0,7);box.hidden=false;box.innerHTML=found.length?found.map(c=>`<button data-search-customer="${c.id}"><b>${esc(c.name)}</b><span>${esc(c.address)} · ${esc(c.status)}</span></button>`).join(''):'<p>No matching sample customers or jobs.</p>';box.querySelectorAll('button').forEach(b=>b.onclick=()=>{box.hidden=true;customerDetail(Number(b.dataset.searchCustomer))})}$('global-search').oninput=globalSearch;$('global-search').addEventListener('keydown',e=>{if(e.key==='Escape')$('search-results').hidden=true});document.addEventListener('click',e=>{if(!e.target.closest('.global-search'))$('search-results').hidden=true});$('notifications').onclick=()=>showDialog(`<h2>Notifications</h2><p class="help">Sample operations and recommendations</p><ul class="activity">${state.logs.slice(0,8).map(l=>`<li>${esc(l)}</li>`).join('')}</ul><a class="button primary" href="activity.html">View all operations</a>`);$('profile').onclick=()=>showDialog(`<p class="eyebrow">SAMPLE OWNER</p><h2>${esc(state.settings.owner)}</h2><p>${esc(state.settings.company)}</p><div class="toolbar"><a href="settings.html" class="button primary">Settings</a><a href="help.html" class="button">Help</a></div><p class="help">Office sample workspace. No operator account has been created.</p>`);updateProfile();function render(){updateValueBadge();({index:overview,routes,customers,financials,agents,growth,activity,valuation,settings,help}[view]||overview)();bindValue()}$('close-dialog').onclick=()=>$('detail').close();$('menu').onclick=()=>{const open=!$('sidebar').classList.contains('open');$('sidebar').classList.toggle('open',open);$('menu').setAttribute('aria-expanded',String(open))};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('sidebar').classList.remove('open');$('menu').setAttribute('aria-expanded','false')}});$('reset').onclick=()=>showDialog('<h2>Reset sample workspace?</h2><p>This removes your browser’s sample changes and restores the fictional starter records.</p><button id="confirm-reset" class="button dark">Reset sample data</button>',()=>{$('confirm-reset').onclick=()=>{state=structuredClone(seed);save();$('detail').close();render();toast('Sample workspace reset.')}});render();if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_sample_workspace',description:'Read fictional Office sample customer counts and completed jobs. No live business records.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||Object.keys(input).length)throw Error('Expected empty input');return{sample:true,customerCount:state.customers.length,completedJobs:state.customers.filter(c=>c.status==='Completed').length}}})).catch(()=>{})}catch{}}})();
